  try {
    browser = await chromium.launch({ executablePath: '/usr/bin/chromium' });
    const page = await browser.newPage();
    const htmlPath = path.join(__dirname, 'index.html');
    const html = fs.readFileSync(htmlPath, 'utf-8');
    await page.setContent(html, { waitUntil: 'load' });
    await page.addScriptTag({ path: '/tmp/axe.min.js' });

    const results = await page.evaluate(async () => {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          if (typeof window.axe !== 'undefined' && window.axe.run) {
            window.axe.run((error, results) => {
              if (error) reject(error);
              else resolve(results);
            });
          } else {
            reject(new Error('axe not loaded'));
          }
        }, 100);
      });
    });

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

    console.log('=== ACCESSIBILITY TEST RESULTS ===');
    console.log(`Total violations found: ${results.violations.length}`);
    console.log(`WCAG violations: ${wcag.length}`);
    console.log(`Best-practice warnings: ${bp.length}`);
    console.log('');

    if (wcag.length > 0) {
      console.log('WCAG VIOLATIONS:');
      wcag.forEach(v => {
        console.log(`  - ${v.id} (${v.impact}): ${v.description}`);
        console.log(`    Targets: ${v.nodes.map(n => n.target).join(', ')}`);
      });
    } else {
      console.log('✓ No WCAG violations found');
    }

    console.log('');

    if (bp.length > 0) {
      console.log('BEST-PRACTICE WARNINGS:');
      bp.forEach(v => {
        console.log(`  - ${v.id}: ${v.description}`);
        console.log(`    Targets: ${v.nodes.map(n => n.target).join(', ')}`);
      });
    } else {
      console.log('✓ No best-practice warnings');
    }

    console.log('');
    console.log(`Passes: ${results.passes.length}`);

    process.exit(wcag.length > 0 ? 1 : 0);
  } catch (error) {
    console.error('Test error:', error.message);
    process.exit(1);
  } finally {
    if (browser) await browser.close();
  }
})();
